          "Hệ lực tác dụng lên đèn cân bằng: <span class=\"math-sym\">T</span><sub style=\"font-size:0.8em\">A</sub> + <span class=\"math-sym\">T</span><sub style=\"font-size:0.8em\">B</sub> + <span class=\"math-sym\">T</span><sub style=\"font-size:0.8em\">C</sub> + <span class=\"math-sym\">P</span> = <span class=\"vec\"><svg class=\"vec-arr\" viewBox=\"0 0 100 20\" preserveAspectRatio=\"none\"><line x1=\"0\" y1=\"10\" x2=\"96\" y2=\"10\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M 82 2 L 98 10 L 82 18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg><span class=\"vec-sym\" style=\"font-style:normal;\">0</span></span>.",
